CREATE FUNCTION public.document_sales_context(p_tenant uuid,p_start date,p_end date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.user_has_tenant(auth.uid(),p_tenant) OR p_end<p_start OR p_end-p_start>60 THEN RAISE EXCEPTION 'Document context scope denied'; END IF;
RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('venue',v.name,'lastReport',(SELECT jsonb_build_object('date',s.date,'number',s.report_number) FROM public.sales_records s WHERE s.tenant_id=p_tenant AND s.venue_id=v.id AND nullif(s.report_number,'') IS NOT NULL ORDER BY s.date DESC LIMIT 1),'missingDays',(SELECT coalesce(jsonb_agg(d::date ORDER BY d), '[]'::jsonb) FROM generate_series(p_start::timestamp,(p_end-1)::timestamp,interval '1 day') d WHERE NOT EXISTS(SELECT 1 FROM public.sales_records s WHERE s.tenant_id=p_tenant AND s.venue_id=v.id AND s.date=d::date::text) AND NOT EXISTS(SELECT 1 FROM public.venue_closures c WHERE c.tenant_id=p_tenant AND c.venue_id=v.id AND c.date=d::date) AND NOT EXISTS(SELECT 1 FROM public.venue_closure_rules r WHERE r.tenant_id=p_tenant AND r.venue_id=v.id AND d::date>=r.start_date AND (r.end_date IS NULL OR d::date<=r.end_date) AND ((r.weekday IS NOT NULL AND extract(dow from d)=r.weekday) OR (r.weekday IS NULL AND r.end_date IS NOT NULL)))))), '[]'::jsonb) FROM public.venues v WHERE v.tenant_id=p_tenant AND v.is_active AND public.user_has_venue(auth.uid(),v.id)); END $$;
REVOKE ALL ON FUNCTION public.document_sales_context(uuid,date,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.document_sales_context(uuid,date,date) TO authenticated;
CREATE TABLE public.finance_source_postings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),source_type text NOT NULL,source_key text NOT NULL,source_record_id uuid,posting_role text NOT NULL DEFAULT 'primary',original_entry_id uuid NOT NULL REFERENCES public.journal_entries(id),current_entry_id uuid NOT NULL REFERENCES public.journal_entries(id),source_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,source_type,source_key,posting_role),UNIQUE(current_entry_id));
GRANT SELECT ON public.finance_source_postings TO authenticated; GRANT ALL ON public.finance_source_postings TO service_role;
ALTER TABLE public.finance_source_postings ENABLE ROW LEVEL SECURITY;
CREATE POLICY source_posting_read ON public.finance_source_postings FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id) AND (public.has_role(auth.uid(),'admin') OR public.is_tenant_admin(tenant_id,auth.uid())) AND EXISTS(SELECT 1 FROM public.journal_entries j WHERE j.id=current_entry_id AND (j.venue_id IS NULL OR public.user_has_venue(auth.uid(),j.venue_id))));
CREATE TABLE public.finance_source_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),source_posting_id uuid REFERENCES public.finance_source_postings(id),original_entry_id uuid NOT NULL REFERENCES public.journal_entries(id),reversal_entry_id uuid NOT NULL REFERENCES public.journal_entries(id),replacement_entry_id uuid REFERENCES public.journal_entries(id),actor_id uuid NOT NULL,reason text NOT NULL,before_snapshot jsonb NOT NULL,after_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,undone_by uuid REFERENCES public.finance_source_operations(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(original_entry_id));
GRANT SELECT ON public.finance_source_operations TO authenticated;GRANT ALL ON public.finance_source_operations TO service_role;
ALTER TABLE public.finance_source_operations ENABLE ROW LEVEL SECURITY;
CREATE POLICY source_operation_read ON public.finance_source_operations FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id) AND (public.has_role(auth.uid(),'admin') OR public.is_tenant_admin(tenant_id,auth.uid())) AND EXISTS(SELECT 1 FROM public.journal_entries j WHERE j.id=original_entry_id AND (j.venue_id IS NULL OR public.user_has_venue(auth.uid(),j.venue_id))));
INSERT INTO public.finance_source_postings(tenant_id,source_type,source_key,source_record_id,original_entry_id,current_entry_id,source_snapshot)
SELECT j.tenant_id,j.source_type,j.source_id,CASE WHEN j.source_id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN j.source_id::uuid END,j.id,j.id,jsonb_build_object('date',j.entry_date,'venue',j.venue,'lines',(SELECT jsonb_agg(jsonb_build_object('account',l.account_id,'debit',l.debit,'credit',l.credit) ORDER BY l.line_no,l.id) FROM public.journal_lines l WHERE l.entry_id=j.id)) FROM public.journal_entries j WHERE j.status='posted' AND j.source_type IN ('sales_summary','invoice','expense_bill','invoice_payment','settlement_clearing','bank_txn','bank_fee','petty_cash') AND nullif(j.source_id,'') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.finance_book_corrections c WHERE c.original_entry_id=j.id AND c.kind IN ('date','reverse')) ON CONFLICT DO NOTHING;
CREATE FUNCTION public.finance_track_source_posting() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'posted') AND NEW.source_type IN ('sales_summary','invoice','expense_bill','invoice_payment','settlement_clearing','bank_txn','bank_fee','petty_cash') AND nullif(NEW.source_id,'') IS NOT NULL THEN
INSERT INTO public.finance_source_postings(tenant_id,source_type,source_key,source_record_id,original_entry_id,current_entry_id,source_snapshot) VALUES(NEW.tenant_id,NEW.source_type,NEW.source_id,CASE WHEN NEW.source_id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN NEW.source_id::uuid END,NEW.id,NEW.id,jsonb_build_object('date',NEW.entry_date,'venue',NEW.venue)) ON CONFLICT DO NOTHING; END IF;RETURN NEW;END $$;
CREATE TRIGGER finance_track_source_posting AFTER INSERT OR UPDATE ON public.journal_entries FOR EACH ROW EXECUTE FUNCTION public.finance_track_source_posting();